function cleanValue(value: string | undefined | null): string {
  return (value ?? '').trim();
}

function uniqueText(values: Array<string | undefined | null>): string[] {
  const seen = new Set<string>();
  const out: string[] = [];

  for (const value of values) {
    const cleaned = cleanValue(value);
    if (!cleaned) continue;
    const key = cleaned.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(cleaned);
  }

  return out;
}

function normalizeProverb(entry: ProverbEntry): ProverbEntry {
  const explanation = cleanValue(entry.explanation);
  const explicitMoral = cleanValue(entry.moral);
  const explicitMeaning = cleanValue(entry.meaning);

  const allMeanings = uniqueText([
    ...(entry.meanings ?? []),
    explicitMeaning,
    explicitMoral,
    ...(entry.morals ?? []),
    entry.answer_english,
  ]).filter(item => item.toLowerCase() !== explanation.toLowerCase());

  const inferredMoral = explicitMoral || cleanValue(entry.morals?.[0]) || allMeanings[0] || '';
  const primaryMeaning = explicitMeaning || inferredMoral || explanation || cleanValue(entry.answer_english);
  const meanings = uniqueText([primaryMeaning, ...allMeanings]);
  const english = cleanValue(entry.english) || cleanValue(entry.literal_translation) || cleanValue(entry.answer_english);

  return {
    ...entry,
    luo: cleanValue(entry.luo),
    english,
    literal_translation: cleanValue(entry.literal_translation) || undefined,
    explanation: explanation || undefined,
    meaning: primaryMeaning || undefined,
    meanings: meanings.length > 0 ? meanings : undefined,
    moral: inferredMoral || undefined,
    morals: inferredMoral ? [inferredMoral] : undefined,
    answer_luo: cleanValue(entry.answer_luo) || undefined,
    answer_english: cleanValue(entry.answer_english) || undefined,
    letter_section: cleanValue(entry.letter_section) || undefined,
  };
}

export const luoProverbs: ProverbEntry[] = rawLuoProverbs.map(normalizeProverb);
